- cards\uFF1A\u5361\u7247\u753B\u5ECA\uFF08\u7B2C\u4E00\u5217\u5E38\u653E\u5C01\u9762\u56FE\u5C5E\u6027\uFF09
- list\uFF1A\u7B80\u5355\u5217\u8868
